#include <stdio.h>

#define MAXN 200000
#define INF 1000000000

int n, q;
int tree[4 * MAXN];  // stores minimum value
int idx[4 * MAXN];   // stores index of that minimum

void build(int node, int l, int r) {
    if (l == r) {
        tree[node] = 0;
        idx[node] = l;
        return;
    }
    int mid = (l + r) / 2;
    build(node * 2, l, mid);
    build(node * 2 + 1, mid + 1, r);
    if (tree[node * 2] <= tree[node * 2 + 1]) {
        tree[node] = tree[node * 2];
        idx[node] = idx[node * 2];
    } else {
        tree[node] = tree[node * 2 + 1];
        idx[node] = idx[node * 2 + 1];
    }
}

void update(int node, int l, int r, int pos, int val) {
    if (l == r) {
        tree[node] = val;
        idx[node] = pos;
        return;
    }
    int mid = (l + r) / 2;
    if (pos <= mid)
        update(node * 2, l, mid, pos, val);
    else
        update(node * 2 + 1, mid + 1, r, pos, val);
    if (tree[node * 2] <= tree[node * 2 + 1]) {
        tree[node] = tree[node * 2];
        idx[node] = idx[node * 2];
    } else {
        tree[node] = tree[node * 2 + 1];
        idx[node] = idx[node * 2 + 1];
    }
}

// Query min value and index in [1, a]
void query(int node, int l, int r, int ql, int qr, int *minv, int *mini) {
    if (ql > r || qr < l) return;
    if (ql <= l && r <= qr) {
        if (tree[node] < *minv || (tree[node] == *minv && idx[node] < *mini)) {
            *minv = tree[node];
            *mini = idx[node];
        }
        return;
    }
    int mid = (l + r) / 2;
    query(node * 2, l, mid, ql, qr, minv, mini);
    query(node * 2 + 1, mid + 1, r, ql, qr, minv, mini);
}

int main() {
    scanf("%d %d", &n, &q);
    build(1, 1, n);

    int ans[n + 1];
    for (int i = 1; i <= n; i++) ans[i] = 0;

    while (q--) {
        int a, b;
        scanf("%d %d", &a, &b);
        for (int i = 0; i < b; i++) {
            int minv = INF, mini = n + 1;
            query(1, 1, n, 1, a, &minv, &mini);
            ans[mini]++;
            update(1, 1, n, mini, minv + 1);
        }
    }

    for (int i = 1; i <= n; i++) {
        printf("%d\n", ans[i]);
    }

    return 0;
}

