int cmp(const void *x, const void *y) {
    // compare pairs (count, index)
    long long *a = (long long*)x, *b = (long long*)y;
    if (a[0] != b[0]) return (a[0] > b[0]) - (a[0] < b[0]);
    return (a[1] > b[1]) - (a[1] < b[1]);
}

