#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    ll val;   // current eaten count
    int idx;  // customer index
} Node;

static Node merge(Node a, Node b) {
    if (a.val != b.val) return (a.val < b.val) ? a : b;
    return (a.idx < b.idx) ? a : b;
}

typedef struct {
    int n;
    Node *seg;
    ll *lazy;
} SegTree;

static void build(SegTree *st, int p, int l, int r) {
    st->lazy[p] = 0;
    if (l == r) {
        st->seg[p].val = 0;
        st->seg[p].idx = l;
        return;
    }
    int m = (l + r) >> 1;
    build(st, p << 1, l, m);
    build(st, p << 1 | 1, m + 1, r);
    st->seg[p] = merge(st->seg[p << 1], st->seg[p << 1 | 1]);
}

static void push(SegTree *st, int p) {
    if (st->lazy[p] != 0) {
        ll v = st->lazy[p];
        int lc = p << 1, rc = p << 1 | 1;
        st->seg[lc].val += v;
        st->seg[rc].val += v;
        st->lazy[lc] += v;
        st->lazy[rc] += v;
        st->lazy[p] = 0;
    }
}

static void range_add(SegTree *st, int p, int l, int r, int ql, int qr, ll v) {
    if (ql > r || qr < l) return;
    if (ql <= l && r <= qr) {
        st->seg[p].val += v;
        st->lazy[p] += v;
        return;
    }
    push(st, p);
    int m = (l + r) >> 1;
    range_add(st, p << 1, l, m, ql, qr, v);
    range_add(st, p << 1 | 1, m + 1, r, ql, qr, v);
    st->seg[p] = merge(st->seg[p << 1], st->seg[p << 1 | 1]);
}

static Node range_min(SegTree *st, int p, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) return st->seg[p];
    push(st, p);
    int m = (l + r) >> 1;
    if (qr <= m) return range_min(st, p << 1, l, m, ql, qr);
    if (ql > m) return range_min(st, p << 1 | 1, m + 1, r, ql, qr);
    Node a = range_min(st, p << 1, l, m, ql, qr);
    Node b = range_min(st, p << 1 | 1, m + 1, r, ql, qr);
    return merge(a, b);
}

static ll point_get(SegTree *st, int p, int l, int r, int pos) {
    if (l == r) return st->seg[p].val;
    push(st, p);
    int m = (l + r) >> 1;
    if (pos <= m) return point_get(st, p << 1, l, m, pos);
    return point_get(st, p << 1 | 1, m + 1, r, pos);
}

int main(void) {
    int N, Q;
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    SegTree st;
    st.n = N;
    st.seg = (Node *)malloc(sizeof(Node) * 4 * (N + 5));
    st.lazy = (ll *)calloc(4 * (N + 5), sizeof(ll));
    build(&st, 1, 1, N);

    for (int qi = 0; qi < Q; qi++) {
        int a;
        ll b;
        scanf("%d %lld", &a, &b);

        Node mn = range_min(&st, 1, 1, N, 1, a);
        ll minv = mn.val;

        // First position in [1..a] with value == minv
        int low = 1, high = a, first = a;
        while (low <= high) {
            int mid = (low + high) >> 1;
            Node cur = range_min(&st, 1, 1, N, 1, mid);
            if (cur.val == minv) {
                first = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        ll len = (ll)(a - first + 1);
        ll full = b / len;
        ll rem = b % len;

        if (full > 0) {
            range_add(&st, 1, 1, N, first, a, full);
        }
        if (rem > 0) {
            range_add(&st, 1, 1, N, first, first + (int)rem - 1, 1);
        }
    }

    for (int i = 1; i <= N; i++) {
        ll ans = point_get(&st, 1, 1, N, i);
        if (i > 1) printf(" ");
        printf("%lld", ans);
    }
    printf("\n");

    free(st.seg);
    free(st.lazy);
    return 0;
}

