struct SegTree {
    int n;
    vector<int> minv, idx, lazy;
    SegTree(int n_) {
        n = 1;
        while (n < n_) n <<= 1;
        minv.assign(2 * n, 0);
        idx.assign(2 * n, 0);
        lazy.assign(2 * n, 0);
        for (int i = 0; i < n_; i++) idx[n + i] = i;
        for (int i = n - 1; i >= 1; i--) idx[i] = idx[2*i];
    }
    void apply(int v, int val) {
        minv[v] += val;
        lazy[v] += val;
    }
    void push(int v) {
        if (lazy[v] != 0) {
            apply(2*v, lazy[v]);
            apply(2*v+1, lazy[v]);
            lazy[v] = 0;
        }
    }
    void add(int l, int r, int val, int v, int tl, int tr) {
        if (l > r) return;
        if (l == tl && r == tr) {
            apply(v, val);
            return;
        }
        push(v);
        int tm = (tl + tr) / 2;
        add(l, min(r, tm), val, 2*v, tl, tm);
        add(max(l, tm+1), r, val, 2*v+1, tm+1, tr);
        if (minv[2*v] < minv[2*v+1]) {
            minv[v] = minv[2*v];
            idx[v] = idx[2*v];
        } else if (minv[2*v] > minv[2*v+1]) {
            minv[v] = minv[2*v+1];
            idx[v] = idx[2*v+1];
        } else {
            minv[v] = minv[2*v];
            idx[v] = min(idx[2*v], idx[2*v+1]);
        }
    }
    pair<int,int> query(int l, int r, int v, int tl, int tr) {
        if (l > r) return {INT_MAX, -1};
        if (l == tl && r == tr) {
            return {minv[v], idx[v]};
        }
        push(v);
        int tm = (tl + tr) / 2;
        auto left = query(l, min(r, tm), 2*v, tl, tm);
        auto right = query(max(l, tm+1), r, 2*v+1, tm+1, tr);
        if (left.first < right.first) return left;
        if (left.first > right.first) return right;
        return {left.first, min(left.second, right.second)};
    }
    void range_add(int l, int r, int val) {
        add(l, r, val, 1, 0, n-1);
    }
    pair<int,int> range_min(int l, int r) {
        return query(l, r, 1, 0, n-1);
    }
};

