#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

struct SegTree {
    int n;
    vector<int64> mn;
    vector<int> idx;
    vector<int64> lazy;

    SegTree(int sz) {
        n = 1;
        while (n < sz) n <<= 1;
        mn.assign(2 * n, 0);
        idx.assign(2 * n, 0);
        lazy.assign(2 * n, 0);

        for (int i = 0; i < n; i++) idx[n + i] = i + 1;
        for (int i = n - 1; i >= 1; i--) pull(i);
    }

    void pull(int x) {
        if (mn[x << 1] < mn[x << 1 | 1]) {
            mn[x] = mn[x << 1];
            idx[x] = idx[x << 1];
        } else if (mn[x << 1] > mn[x << 1 | 1]) {
            mn[x] = mn[x << 1 | 1];
            idx[x] = idx[x << 1 | 1];
        } else {
            mn[x] = mn[x << 1];
            idx[x] = min(idx[x << 1], idx[x << 1 | 1]);
        }
    }

    void apply(int x, int64 v) {
        mn[x] += v;
        lazy[x] += v;
    }

    void push(int x) {
        if (lazy[x] != 0) {
            apply(x << 1, lazy[x]);
            apply(x << 1 | 1, lazy[x]);
            lazy[x] = 0;
        }
    }

    pair<int64,int> queryMin(int l, int r, int x, int lx, int rx) {
        if (r < lx || rx < l) return {(int64)4e18, (int)1e9};
        if (l <= lx && rx <= r) return {mn[x], idx[x]};
        push(x);
        int mid = (lx + rx) >> 1;
        auto a = queryMin(l, r, x << 1, lx, mid);
        auto b = queryMin(l, r, x << 1 | 1, mid + 1, rx);
        if (a.first < b.first) return a;
        if (a.first > b.first) return b;
        return {a.first, min(a.second, b.second)};
    }

    pair<int64,int> queryMin(int l, int r) {
        return queryMin(l, r, 1, 1, n);
    }

    void rangeAdd(int l, int r, int64 v, int x, int lx, int rx) {
        if (r < lx || rx < l) return;
        if (l <= lx && rx <= r) {
            apply(x, v);
            return;
        }
        push(x);
        int mid = (lx + rx) >> 1;
        rangeAdd(l, r, v, x << 1, lx, mid);
        rangeAdd(l, r, v, x << 1 | 1, mid + 1, rx);
        pull(x);
    }

    void rangeAdd(int l, int r, int64 v) {
        if (l > r) return;
        rangeAdd(l, r, v, 1, 1, n);
    }

    int64 pointQuery(int p, int x, int lx, int rx) {
        if (lx == rx) return mn[x];
        push(x);
        int mid = (lx + rx) >> 1;
        if (p <= mid) return pointQuery(p, x << 1, lx, mid);
        return pointQuery(p, x << 1 | 1, mid + 1, rx);
    }

    int64 pointQuery(int p) {
        return pointQuery(p, 1, 1, n);
    }

    int findFirstLessEqual(int l, int r, int64 val, int x, int lx, int rx) {
        if (r < lx || rx < l || mn[x] > val) return -1;
        if (lx == rx) return lx;
        push(x);
        int mid = (lx + rx) >> 1;
        int res = findFirstLessEqual(l, r, val, x << 1, lx, mid);
        if (res != -1) return res;
        return findFirstLessEqual(l, r, val, x << 1 | 1, mid + 1, rx);
    }

    int findFirstLessEqual(int l, int r, int64 val) {
        return findFirstLessEqual(l, r, val, 1, 1, n);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    SegTree st(N);

    for (int qi = 0; qi < Q; qi++) {
        int a;
        int64 b;
        cin >> a >> b;

        auto cur = st.queryMin(1, a);
        int64 m = cur.first;

        int pos = st.findFirstLessEqual(1, a, m + 1);
        int k = (pos == -1 ? a + 1 : pos) - 1; // [1..k] are exactly m or m+1? Actually [1..k] all <= m+1, but by construction after operations diff <=1.

        // Number of people among first a having minimum m
        // In this process counts in prefix differ by at most 1, so those with minimum are exactly first t positions before first m+1.
        int64 cntMin = 0;
        if (pos == -1) cntMin = a;
        else {
            // find first position with value >= m+1, i.e. > m
            // since all values are m or m+1, minimum positions are exactly before pos
            cntMin = pos - 1;
        }

        // Safer way if all first a are m
        if (cntMin == 0 && cur.second == 1) {
            // fallback shouldn't happen
            cntMin = a;
        }

        int64 full = b / a;
        int64 rem = b % a;

        if (full) st.rangeAdd(1, a, full);

        // Initially, among first a, values are either m or m+1 and minima are the first cntMin positions.
        // After adding 'full' to all, same structure remains.
        // Next rem selections go to current minima in order.
        // If rem <= cntMin: add 1 to first rem minima => positions [1..rem]
        // else: first cntMin get one, then wrap and next rem-cntMin minima are positions [cntMin+1 .. rem]
        if (rem > 0) {
            if (rem <= cntMin) {
                st.rangeAdd(1, (int)rem, 1);
            } else {
                st.rangeAdd(1, (int)cntMin, 1);
                st.rangeAdd((int)cntMin + 1, (int)rem, 1);
            }
        }
    }

    for (int i = 1; i <= N; i++) {
        if (i > 1) cout << ' ';
        cout << st.pointQuery(i);
    }
    cout << '\n';
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int Q = Integer.parseInt(st.nextToken());

        long[] eaten = new long[N + 1];
        // Segment tree for range minimum query (value, index)
        // We store pairs: (eaten count, index)
        long[] minVal = new long[4 * N];
        int[] minIdx = new int[4 * N];

        build(1, 1, N, minVal, minIdx, eaten);

        while (Q-- > 0) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());

            for (int i = 0; i < b; i++) {
                // Query minimum in range [1, a]
                long[] res = query(1, 1, N, 1, a, minVal, minIdx);
                int idx = (int) res[1];
                eaten[idx]++;
                // Update the tree
                update(1, 1, N, idx, minVal, minIdx, eaten);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= N; i++) {
            sb.append(eaten[i]).append("\n");
        }
        System.out.print(sb);
    }

    static void build(int node, int l, int r, long[] minVal, int[] minIdx, long[] eaten) {
        if (l == r) {
            minVal[node] = eaten[l];
            minIdx[node] = l;
            return;
        }
        int mid = (l + r) / 2;
        build(node * 2, l, mid, minVal, minIdx, eaten);
        build(node * 2 + 1, mid + 1, r, minVal, minIdx, eaten);
        // Combine
        if (minVal[node * 2] < minVal[node * 2 + 1]) {
            minVal[node] = minVal[node * 2];
            minIdx[node] = minIdx[node * 2];
        } else if (minVal[node * 2] > minVal[node * 2 + 1]) {
            minVal[node] = minVal[node * 2 + 1];
            minIdx[node] = minIdx[node * 2 + 1];
        } else {
            // equal: choose smaller index
            minVal[node] = minVal[node * 2];
            minIdx[node] = Math.min(minIdx[node * 2], minIdx[node * 2 + 1]);
        }
    }

    static long[] query(int node, int l, int r, int ql, int qr, long[] minVal, int[] minIdx) {
        if (ql <= l && r <= qr) {
            return new long[]{minVal[node], minIdx[node]};
        }
        int mid = (l + r) / 2;
        long[] leftRes = null;
        long[] rightRes = null;
        if (ql <= mid) {
            leftRes = query(node * 2, l, mid, ql, qr, minVal, minIdx);
        }
        if (qr > mid) {
            rightRes = query(node * 2 + 1, mid + 1, r, ql, qr, minVal, minIdx);
        }
        if (leftRes == null) return rightRes;
        if (rightRes == null) return leftRes;
        if (leftRes[0] < rightRes[0]) return leftRes;
        if (leftRes[0] > rightRes[0]) return rightRes;
        // equal
        return leftRes[1] < rightRes[1] ? leftRes : rightRes;
    }

    static void update(int node, int l, int r, int pos, long[] minVal, int[] minIdx, long[] eaten) {
        if (l == r) {
            minVal[node] = eaten[pos];
            minIdx[node] = pos;
            return;
        }
        int mid = (l + r) / 2;
        if (pos <= mid) {
            update(node * 2, l, mid, pos, minVal, minIdx, eaten);
        } else {
            update(node * 2 + 1, mid + 1, r, pos, minVal, minIdx, eaten);
        }
        if (minVal[node * 2] < minVal[node * 2 + 1]) {
            minVal[node] = minVal[node * 2];
            minIdx[node] = minIdx[node * 2];
        } else if (minVal[node * 2] > minVal[node * 2 + 1]) {
            minVal[node] = minVal[node * 2 + 1];
            minIdx[node] = minIdx[node * 2 + 1];
        } else {
            minVal[node] = minVal[node * 2];
            minIdx[node] = Math.min(minIdx[node * 2], minIdx[node * 2 + 1]);
        }
    }
}

