            while (b > 0) {
                long minVal = Long.MAX_VALUE;
                long cnt = 0;
                for (int i = 1; i <= a; i++) {
                    if (eaten[i] < minVal) { minVal = eaten[i]; cnt = 1; }
                    else if (eaten[i] == minVal) cnt++;
                }
                // Each of the cnt customers at minVal gets at least floor(b/cnt)
                // and b%cnt of them (smallest numbered) get one extra
                long perPerson = b / cnt;
                long extra = b % cnt;
                long extraGiven = 0;
                for (int i = 1; i <= a && (perPerson > 0 || extraGiven < extra); i++) {
                    if (eaten[i] == minVal) {
                        eaten[i] += perPerson + (extraGiven < extra ? 1 : 0);
                        if (extraGiven < extra) extraGiven++;
                    }
                }
                b = 0;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= N; i++) sb.append(eaten[i]).append("\n");
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class SegTree {
        int n;
        long[] min;
        long[] lazy;

        SegTree(int size) {
            n = 1;
            while (n < size) n <<= 1;
            min = new long[n << 1];
            lazy = new long[n << 1];
        }

        void push(int node) {
            if (lazy[node] != 0) {
                long v = lazy[node];
                int l = node << 1, r = l | 1;
                min[l] += v;
                min[r] += v;
                lazy[l] += v;
                lazy[r] += v;
                lazy[node] = 0;
            }
        }

        void rangeAdd(int l, int r, long val) {
            rangeAdd(l, r, val, 1, 0, n);
        }

        void rangeAdd(int l, int r, long val, int node, int nl, int nr) {
            if (r <= nl || nr <= l) return;
            if (l <= nl && nr <= r) {
                min[node] += val;
                lazy[node] += val;
                return;
            }
            push(node);
            int mid = (nl + nr) >>> 1;
            rangeAdd(l, r, val, node << 1, nl, mid);
            rangeAdd(l, r, val, node << 1 | 1, mid, nr);
            min[node] = Math.min(min[node << 1], min[node << 1 | 1]);
        }

        long rangeMin(int l, int r) {
            return rangeMin(l, r, 1, 0, n);
        }

        long rangeMin(int l, int r, int node, int nl, int nr) {
            if (r <= nl || nr <= l) return Long.MAX_VALUE / 4;
            if (l <= nl && nr <= r) return min[node];
            push(node);
            int mid = (nl + nr) >>> 1;
            return Math.min(rangeMin(l, r, node << 1, nl, mid),
                            rangeMin(l, r, node << 1 | 1, mid, nr));
        }

        int findFirstEqual(int l, int r, long target) {
            return findFirstEqual(l, r, target, 1, 0, n);
        }

        int findFirstEqual(int l, int r, long target, int node, int nl, int nr) {
            if (r <= nl || nr <= l || min[node] > target) return -1;
            if (nr - nl == 1) return nl;
            push(node);
            int mid = (nl + nr) >>> 1;
            int res = findFirstEqual(l, r, target, node << 1, nl, mid);
            if (res != -1) return res;
            return findFirstEqual(l, r, target, node << 1 | 1, mid, nr);
        }

        void collect(long[] ans, int node, int nl, int nr, long acc) {
            acc += lazy[node];
            if (nr - nl == 1) {
                if (nl < ans.length) ans[nl] = min[node];
                return;
            }
            int mid = (nl + nr) >>> 1;
            collect(ans, node << 1, nl, mid, acc);
            collect(ans, node << 1 | 1, mid, nr, acc);
        }

        long[] getAll(int size) {
            long[] ans = new long[size];
            collectLeaves(1, 0, n, 0, ans, size);
            return ans;
        }

        void collectLeaves(int node, int nl, int nr, long add, long[] ans, int size) {
            add += lazy[node];
            if (nr - nl == 1) {
                if (nl < size) ans[nl] = min[node];
                return;
            }
            int mid = (nl + nr) >>> 1;
            collectLeaves(node << 1, nl, mid, add, ans, size);
            collectLeaves(node << 1 | 1, mid, nr, add, ans, size);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int Q = fs.nextInt();

        SegTree st = new SegTree(N);

        for (int qi = 0; qi < Q; qi++) {
            int a = fs.nextInt();
            long b = fs.nextLong();

            long mn = st.rangeMin(0, a);
            int pos = st.findFirstEqual(0, a, mn);

            long cntMin = 0;
            int cur = pos;
            while (cur < a) {
                long nowMin = st.rangeMin(cur, a);
                if (nowMin != mn) break;
                int p = st.findFirstEqual(cur, a, mn);
                if (p == -1) break;
                cntMin++;
                cur = p + 1;
            }

            long fullRounds = b / cntMin;
            long rem = b % cntMin;

            if (fullRounds > 0) st.rangeAdd(0, a, fullRounds);

            cur = pos;
            while (rem > 0 && cur < a) {
                long nowMin = st.rangeMin(cur, a);
                if (nowMin != mn + fullRounds) break;
                int p = st.findFirstEqual(cur, a, mn + fullRounds);
                if (p == -1) break;
                st.rangeAdd(p, p + 1, 1);
                rem--;
                cur = p + 1;
            }
        }

        long[] ans = st.getAll(N);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            if (i > 0) sb.append(' ');
            sb.append(ans[i]);
        }
        System.out.println(sb);
    }
}

import sys
input = sys.stdin.readline

class SegTree:
    def __init__(self, n):
        self.n = n
        size = 1
        while size < n:
            size <<= 1
        self.size = size
        # Each node stores (min_value, index)
        self.data = [(0, i) for i in range(size * 2)]
        # Initialize leaves
        for i in range(n):
            self.data[size + i] = (0, i)
        for i in range(size - 1, 0, -1):
            self._pull(i)

    def _pull(self, idx):
        left = self.data[idx * 2]
        right = self.data[idx * 2 + 1]
        if left[0] < right[0] or (left[0] == right[0] and left[1] < right[1]):
            self.data[idx] = left
        else:
            self.data[idx] = right

    def update(self, pos, val):
        i = pos + self.size
        self.data[i] = (val, pos)
        i //= 2
        while i:
            self._pull(i)
            i //= 2

    def query(self, l, r):
        # query on [l, r)
        l += self.size
        r += self.size
        res = (10**9, -1)
        while l < r:
            if l & 1:
                if self.data[l][0] < res[0] or (self.data[l][0] == res[0] and self.data[l][1] < res[1]):
                    res = self.data[l]
                l += 1
            if r & 1:
                r -= 1
                if self.data[r][0] < res[0] or (self.data[r][0] == res[0] and self.data[r][1] < res[1]):
                    res = self.data[r]
            l //= 2
            r //= 2
        return res

def main():
    N, Q = map(int, input().split())
    seg = SegTree(N)
    for _ in range(Q):
        a, b = map(int, input().split())
        for _ in range(b):
            min_val, idx = seg.query(0, a)
            seg.update(idx, min_val + 1)
    ans = [seg.query(i, i+1)[0] for i in range(N)]
    print("\n".join(map(str, ans)))

if __name__ == "__main__":
    main()
